    out = [row[:] for row in grid]
    background = max(
        {v for row in grid for v in row},
        key=lambda v: sum(row.count(v) for row in grid)
    )

    # Find background cells reachable from the edge without crossing marks.
    seen = set()
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background:
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background:
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        if (r, c) in seen or grid[r][c] != background:
            continue
        seen.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                stack.append((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in seen:
                out[r][c] = 3
    return out
